BEGIN;
CREATE TABLE knowledge_taxonomy_version(tenant_id uuid NOT NULL,workspace_id uuid NOT NULL,taxonomy_id uuid NOT NULL,version_id uuid NOT NULL,owner_id uuid NOT NULL,author_id uuid NOT NULL,version integer NOT NULL CHECK(version>0),state text NOT NULL CHECK(state IN('draft','in_review','published','superseded','retired')),governance_version bigint NOT NULL DEFAULT 1 CHECK(governance_version>0),reason_hash text CHECK(reason_hash~'^sha256:[a-f0-9]{64}$'),created_at timestamptz NOT NULL,PRIMARY KEY(tenant_id,workspace_id,taxonomy_id,version_id),FOREIGN KEY(tenant_id,owner_id)REFERENCES iam_user(tenant_id,user_id)ON DELETE RESTRICT,UNIQUE(tenant_id,workspace_id,taxonomy_id,version));
CREATE UNIQUE INDEX one_published_taxonomy_version ON knowledge_taxonomy_version(tenant_id,workspace_id,taxonomy_id)WHERE state='published';
CREATE TABLE knowledge_taxonomy_term(tenant_id uuid NOT NULL,workspace_id uuid NOT NULL,taxonomy_id uuid NOT NULL,version_id uuid NOT NULL,canonical_key text NOT NULL CHECK(canonical_key~'^[a-z][a-z0-9-]{1,79}$'),label text NOT NULL CHECK(char_length(label)BETWEEN 2 AND 120),definition text NOT NULL CHECK(char_length(definition)BETWEEN 10 AND 2000),parent_key text,synonyms jsonb NOT NULL CHECK(jsonb_typeof(synonyms)='array'AND jsonb_array_length(synonyms)<=20),status text NOT NULL CHECK(status IN('active','deprecated')),replacement_key text,PRIMARY KEY(tenant_id,workspace_id,taxonomy_id,version_id,canonical_key),FOREIGN KEY(tenant_id,workspace_id,taxonomy_id,version_id)REFERENCES knowledge_taxonomy_version(tenant_id,workspace_id,taxonomy_id,version_id)ON DELETE RESTRICT);
CREATE TABLE knowledge_taxonomy_assignment(tenant_id uuid NOT NULL,workspace_id uuid NOT NULL,assignment_id text NOT NULL CHECK(assignment_id~'^[a-f0-9]{64}$'),asset_id uuid NOT NULL,asset_version_id uuid NOT NULL,taxonomy_id uuid NOT NULL,taxonomy_version_id uuid NOT NULL,asset_type text NOT NULL CHECK(asset_type IN('policy','procedure','report','record','dataset')),term_keys jsonb NOT NULL CHECK(jsonb_typeof(term_keys)='array'AND jsonb_array_length(term_keys)BETWEEN 1 AND 20),classification text NOT NULL CHECK(classification IN('public','internal','confidential','restricted')),method text NOT NULL CHECK(method IN('rule','human','model_suggestion')),confidence numeric(4,3) NOT NULL CHECK(confidence BETWEEN 0 AND 1),state text NOT NULL CHECK(state IN('unclassified','candidate','reviewed','confirmed')),created_at timestamptz NOT NULL,PRIMARY KEY(tenant_id,workspace_id,assignment_id),FOREIGN KEY(tenant_id,workspace_id,asset_id,asset_version_id)REFERENCES knowledge_version_governance(tenant_id,workspace_id,asset_id,version_id)ON DELETE RESTRICT,FOREIGN KEY(tenant_id,workspace_id,taxonomy_id,taxonomy_version_id)REFERENCES knowledge_taxonomy_version(tenant_id,workspace_id,taxonomy_id,version_id)ON DELETE RESTRICT,UNIQUE(tenant_id,workspace_id,asset_version_id,taxonomy_id,taxonomy_version_id));
CREATE TABLE knowledge_taxonomy_reprocessing(tenant_id uuid NOT NULL,workspace_id uuid NOT NULL,plan_id text NOT NULL CHECK(plan_id~'^[a-f0-9]{64}$'),taxonomy_id uuid NOT NULL,from_version_id uuid NOT NULL,to_version_id uuid NOT NULL,estimated_assets integer NOT NULL CHECK(estimated_assets>=0),batch_size integer NOT NULL CHECK(batch_size BETWEEN 1 AND 100),fencing_token bigint NOT NULL DEFAULT 0 CHECK(fencing_token>=0),state text NOT NULL CHECK(state IN('pending','running','completed','failed')),cursor_hash text,created_at timestamptz NOT NULL,PRIMARY KEY(tenant_id,workspace_id,plan_id),FOREIGN KEY(tenant_id,workspace_id,taxonomy_id,from_version_id)REFERENCES knowledge_taxonomy_version(tenant_id,workspace_id,taxonomy_id,version_id)ON DELETE RESTRICT,FOREIGN KEY(tenant_id,workspace_id,taxonomy_id,to_version_id)REFERENCES knowledge_taxonomy_version(tenant_id,workspace_id,taxonomy_id,version_id)ON DELETE RESTRICT);
CREATE TABLE knowledge_taxonomy_outbox(tenant_id uuid NOT NULL,workspace_id uuid NOT NULL,event_id uuid NOT NULL,event_type text NOT NULL CHECK(event_type IN('knowledge.taxonomy.published.v1','knowledge.taxonomy.superseded.v1','knowledge.taxonomy.assignment.review_required.v1','knowledge.taxonomy.assignment.confirmed.v1','knowledge.taxonomy.reprocessing.requested.v1','knowledge.taxonomy.reprocessing.completed.v1')),request_id uuid NOT NULL,taxonomy_id uuid NOT NULL,version_id uuid NOT NULL,state text NOT NULL,governance_version bigint NOT NULL,occurred_at timestamptz NOT NULL,published_at timestamptz,PRIMARY KEY(tenant_id,workspace_id,event_id),FOREIGN KEY(tenant_id,workspace_id,taxonomy_id,version_id)REFERENCES knowledge_taxonomy_version(tenant_id,workspace_id,taxonomy_id,version_id)ON DELETE RESTRICT);
REVOKE ALL ON knowledge_taxonomy_version,knowledge_taxonomy_term,knowledge_taxonomy_assignment,knowledge_taxonomy_reprocessing,knowledge_taxonomy_outbox FROM PUBLIC;GRANT SELECT,INSERT,UPDATE(state,governance_version,reason_hash)ON knowledge_taxonomy_version TO domus_knowledge_runtime;GRANT SELECT,INSERT ON knowledge_taxonomy_term,knowledge_taxonomy_assignment,knowledge_taxonomy_outbox TO domus_knowledge_runtime;GRANT SELECT,INSERT,UPDATE(fencing_token,state,cursor_hash)ON knowledge_taxonomy_reprocessing TO domus_knowledge_runtime;
ALTER TABLE knowledge_taxonomy_version ENABLE ROW LEVEL SECURITY;ALTER TABLE knowledge_taxonomy_version FORCE ROW LEVEL SECURITY;ALTER TABLE knowledge_taxonomy_term ENABLE ROW LEVEL SECURITY;ALTER TABLE knowledge_taxonomy_term FORCE ROW LEVEL SECURITY;ALTER TABLE knowledge_taxonomy_assignment ENABLE ROW LEVEL SECURITY;ALTER TABLE knowledge_taxonomy_assignment FORCE ROW LEVEL SECURITY;ALTER TABLE knowledge_taxonomy_reprocessing ENABLE ROW LEVEL SECURITY;ALTER TABLE knowledge_taxonomy_reprocessing FORCE ROW LEVEL SECURITY;ALTER TABLE knowledge_taxonomy_outbox ENABLE ROW LEVEL SECURITY;ALTER TABLE knowledge_taxonomy_outbox FORCE ROW LEVEL SECURITY;
CREATE POLICY taxonomy_version_scope ON knowledge_taxonomy_version TO domus_knowledge_runtime USING(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'))WITH CHECK(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'));CREATE POLICY taxonomy_term_scope ON knowledge_taxonomy_term TO domus_knowledge_runtime USING(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'))WITH CHECK(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'));CREATE POLICY taxonomy_assignment_scope ON knowledge_taxonomy_assignment TO domus_knowledge_runtime USING(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'))WITH CHECK(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'));CREATE POLICY taxonomy_reprocessing_scope ON knowledge_taxonomy_reprocessing TO domus_knowledge_runtime USING(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'))WITH CHECK(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'));CREATE POLICY taxonomy_outbox_scope ON knowledge_taxonomy_outbox TO domus_knowledge_runtime USING(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'))WITH CHECK(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'));
INSERT INTO schema_migrations(version,description)VALUES(17,'V1-407 versioned taxonomy and assignments')ON CONFLICT(version)DO NOTHING;COMMIT;
